"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([[83335],{50990:e=>{e.exports=JSON.parse('{"tag":{"label":"Ferrets","permalink":"/docs/tags/ferrets","allTagsPath":"/docs/tags","count":23,"items":[{"id":"general-care/health-and-medical/skin-issues","title":"A Guide to Common Skin Issues in Small Pets","description":"A comprehensive guide to identifying, preventing, and treating common skin problems in small exotic pets, including urine scald, mites, ringworm, and bacterial infections, with species-specific advice.","permalink":"/docs/general-care/health-and-medical/skin-issues"},{"id":"Ferrets/illnesses-and-conditions/adrenal-disease","title":"Adrenal Gland Disease in Ferrets","description":"An in-depth guide to adrenal gland disease in ferrets, a common and serious condition characterized by hair loss, discussing its causes, signs, diagnosis, and treatment options.","permalink":"/docs/Ferrets/illnesses-and-conditions/adrenal-disease"},{"id":"Ferrets/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Ferrets","description":"An overview of the most common health issues affecting pet ferrets, with a strong emphasis on cancers like adrenal disease, insulinoma, and lymphoma, as well as heart disease and GI obstructions.","permalink":"/docs/Ferrets/illnesses-and-conditions/common-health-issues"},{"id":"Ferrets/health-and-wellness/dental-health","title":"Dental Health in Ferrets","description":"A guide to dental health in ferrets, covering common issues like fractured teeth and tartar buildup, and outlining the importance of preventative care, including diet and tooth brushing.","permalink":"/docs/Ferrets/health-and-wellness/dental-health"},{"id":"Ferrets/getting-started/essential-supplies","title":"Essential Supplies for Pet Ferrets","description":"A complete checklist of the essential supplies needed to create a safe, stimulating, and comfortable home for pet ferrets.","permalink":"/docs/Ferrets/getting-started/essential-supplies"},{"id":"Ferrets/health-and-wellness/eye-and-vision-issues","title":"Eye & Vision Issues in Ferrets","description":"A guide to common eye and vision issues in ferrets, discussing their naturally poor eyesight and common age-related problems like cataracts and retinal atrophy.","permalink":"/docs/Ferrets/health-and-wellness/eye-and-vision-issues"},{"id":"Ferrets/getting-started/ferret-basic-care","title":"Ferret Basic Care","description":"Ferrets are playful, curious, and energetic members of the weasel family. They can make wonderful, engaging pets, but they have very specific care requirements that differ significantly from rodents. Understanding their needs is key to providing a healthy and enriching life.","permalink":"/docs/Ferrets/getting-started/ferret-basic-care"},{"id":"Ferrets/getting-started/ferret-habitat","title":"Ferret Habitat","description":"Ferrets are intelligent, playful, and incredibly curious. Their habitat needs to be a safe and secure home base, but it is not where they should spend all their time. A ferret\'s cage is for sleeping,...","permalink":"/docs/Ferrets/getting-started/ferret-habitat"},{"id":"Ferrets/getting-started/ferret-nutrition","title":"Ferret Nutrition","description":"Understanding a ferret\'s diet is simple: they are obligate carnivores. This means their bodies are designed to digest and thrive on animal-based protein and fat exclusively. They cannot digest fiber,...","permalink":"/docs/Ferrets/getting-started/ferret-nutrition"},{"id":"Ferrets/health-and-wellness/gi-health","title":"Gastrointestinal (GI) Health in Ferrets","description":"A guide to gastrointestinal (GI) health in ferrets, covering their unique digestive system and common issues like foreign body obstructions, vomiting, diarrhea, and ECE.","permalink":"/docs/Ferrets/health-and-wellness/gi-health"},{"id":"Ferrets/getting-started/grooming-your-ferret","title":"Grooming Your Pet Ferret","description":"A guide to the essential grooming practices for pet ferrets, including nail trimming, ear cleaning, and bathing.","permalink":"/docs/Ferrets/getting-started/grooming-your-ferret"},{"id":"Ferrets/illnesses-and-conditions/heart-disease","title":"Heart Disease in Ferrets","description":"A guide to heart disease in ferrets, a common condition in middle-aged and older animals, covering the signs of congestive heart failure, diagnosis, and medical management.","permalink":"/docs/Ferrets/illnesses-and-conditions/heart-disease"},{"id":"Ferrets/health-and-wellness/home-health-care","title":"Home Health Care for Pet Ferrets","description":"A guide to performing regular at-home health checks for your pet ferrets to monitor their well-being and detect early signs of common illnesses.","permalink":"/docs/Ferrets/health-and-wellness/home-health-care"},{"id":"Ferrets/illnesses-and-conditions/insulinoma","title":"Insulinoma in Ferrets","description":"An in-depth guide to insulinoma in ferrets, a common pancreatic cancer that causes dangerously low blood sugar, covering the signs, emergency care, diagnosis, and treatment.","permalink":"/docs/Ferrets/illnesses-and-conditions/insulinoma"},{"id":"Ferrets/getting-started/is-a-ferret-right-for-me","title":"Is a Ferret Right for Me and My Family?","description":"Ferrets are playful, mischievous, and deeply entertaining companions \u2014 often described as \'cats in a slinky body.\' They are also one of the more demanding small pets, with significant time...","permalink":"/docs/Ferrets/getting-started/is-a-ferret-right-for-me"},{"id":"Ferrets/breeds-and-genetics/know-your-ferret-colors","title":"Know Your Ferret Colors & Patterns","description":"A guide to ferret coat colors, patterns, and markings recognized by the American Ferret Association.","permalink":"/docs/Ferrets/breeds-and-genetics/know-your-ferret-colors"},{"id":"Ferrets/illnesses-and-conditions/lymphoma","title":"Lymphoma in Ferrets","description":"An in-depth guide to lymphoma, the most common cancer in ferrets, covering its different forms (juvenile and adult), signs, diagnosis, and chemotherapy treatment.","permalink":"/docs/Ferrets/illnesses-and-conditions/lymphoma"},{"id":"Ferrets/health-and-wellness/parasites","title":"Parasites in Ferrets","description":"A guide to common parasites affecting ferrets, including ear mites, fleas, and the serious threat of heartworm disease, as well as internal parasites like coccidia.","permalink":"/docs/Ferrets/health-and-wellness/parasites"},{"id":"Ferrets/getting-started/proper-handling","title":"Proper Handling of Pet Ferrets","description":"A guide to the correct and safe methods for handling pet ferrets, including how to pick them up and the use of scruffing for training and procedures.","permalink":"/docs/Ferrets/getting-started/proper-handling"},{"id":"Ferrets/health-and-wellness/respiratory-issues","title":"Respiratory Issues in Ferrets","description":"A guide to respiratory issues in ferrets, covering their unique susceptibility to the human influenza virus, as well as other causes of respiratory distress like pneumonia and heart disease.","permalink":"/docs/Ferrets/health-and-wellness/respiratory-issues"},{"id":"Ferrets/breeds-and-genetics/sexing-your-ferret","title":"Sexing Your Pet Ferret","description":"A simple guide to determining the sex of a pet ferret by identifying the key anatomical differences between males and females.","permalink":"/docs/Ferrets/breeds-and-genetics/sexing-your-ferret"},{"id":"Ferrets/illnesses-and-conditions/diabetes-in-ferrets","title":"Understanding Diabetes in Ferrets","description":"When discussing pancreatic diseases in ferrets, it is crucial to distinguish between two very different conditions: Insulinoma and Diabetes Mellitus.","permalink":"/docs/Ferrets/illnesses-and-conditions/diabetes-in-ferrets"},{"id":"Ferrets/health-and-wellness/understanding-ferret-behavior","title":"Understanding Ferret Behavior: A Guide for Owners","description":"Ferrets are playful, mischievous, and highly social animals with a personality that is often described as a cross between a cat and a dog. Understanding their unique behaviors is key to a happy, healthy ferret.","permalink":"/docs/Ferrets/health-and-wellness/understanding-ferret-behavior"}],"unlisted":false}}')}}]);